// Consistent hash ring with virtual nodes
import { createHash } from 'crypto';

class ConsistentHashRing {
  constructor(virtualNodes = 150) {
    this.virtualNodes = virtualNodes;
    this.ring = new Map();    // position (number) -> server name
    this.sortedKeys = [];     // sorted array of all ring positions
  }

  _hash(key) {
    // MD5, take first 8 hex chars -> 32-bit unsigned integer
    const hex = createHash('md5').update(key).digest('hex').slice(0, 8);
    return parseInt(hex, 16); // value in [0, 2^32)
  }

  addServer(server) {
    for (let i = 0; i < this.virtualNodes; i++) {
      const vnodeKey = `${server}#vnode${i}`;
      const position = this._hash(vnodeKey);
      this.ring.set(position, server);
      this.sortedKeys.push(position);
    }
    // Keep sorted for binary search
    this.sortedKeys.sort((a, b) => a - b);
  }

  removeServer(server) {
    for (let i = 0; i < this.virtualNodes; i++) {
      const position = this._hash(`${server}#vnode${i}`);
      this.ring.delete(position);
    }
    // Rebuild sorted array (only remaining positions)
    this.sortedKeys = this.sortedKeys.filter(k => this.ring.has(k));
  }

  getServer(key) {
    if (this.sortedKeys.length === 0) throw new Error('Ring is empty');
    const hash = this._hash(key);

    // Binary search: find first position >= hash
    let lo = 0, hi = this.sortedKeys.length;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (this.sortedKeys[mid] < hash) lo = mid + 1;
      else hi = mid;
    }

    // Wrap around if past the last position (circular ring)
    const idx = lo % this.sortedKeys.length;
    return this.ring.get(this.sortedKeys[idx]);
  }

  // Show load distribution for a set of test keys
  analyzeDistribution(testKeys) {
    const counts = {};
    for (const key of testKeys) {
      const server = this.getServer(key);
      counts[server] = (counts[server] || 0) + 1;
    }
    return counts;
  }
}

// --- Usage ---
const ring = new ConsistentHashRing(150);
['cache-1', 'cache-2', 'cache-3'].forEach(s => ring.addServer(s));

console.log(ring.getServer('user:42'));    // e.g. 'cache-2'
console.log(ring.getServer('session:99')); // e.g. 'cache-1'

// Adding a server only remaps ~25% of keys
ring.addServer('cache-4');
console.log(ring.getServer('user:42'));    // likely still 'cache-2'

// Distribution check with 10,000 test keys
const keys = Array.from({ length: 10000 }, (_, i) => `key:${i}`);
console.log(ring.analyzeDistribution(keys));
// Typical output: { 'cache-1': 2487, 'cache-2': 2531, 'cache-3': 2493, 'cache-4': 2489 }
// Each server gets ~25% ± a few percent

// Replication with consistent hashing
// Returns R distinct physical servers clockwise from key's position
function getReplicaSet(ring, key, replicaFactor) {
  if (ring.sortedKeys.length === 0) throw new Error('Empty ring');

  const hash = ring._hash(key);
  const replicas = [];
  const seen = new Set(); // deduplicate physical servers

  // Find starting index (first vnode >= hash)
  let lo = 0, hi = ring.sortedKeys.length;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (ring.sortedKeys[mid] < hash) lo = mid + 1;
    else hi = mid;
  }

  // Walk clockwise collecting distinct servers
  const total = ring.sortedKeys.length;
  for (let i = 0; i < total && replicas.length < replicaFactor; i++) {
    const idx = (lo + i) % total;
    const server = ring.ring.get(ring.sortedKeys[idx]);
    if (!seen.has(server)) {
      seen.add(server);
      replicas.push(server);
    }
  }

  if (replicas.length < replicaFactor) {
    throw new Error(`Only ${replicas.length} servers for factor ${replicaFactor}`);
  }
  return replicas; // [primary, replica1, replica2, ...]
}

// --- Example usage ---
const ring2 = new ConsistentHashRing(150);
['db-node-1', 'db-node-2', 'db-node-3', 'db-node-4'].forEach(s => ring2.addServer(s));

const replicas = getReplicaSet(ring2, 'user:42', 3);
console.log(replicas); // e.g. ['db-node-3', 'db-node-1', 'db-node-4']
// Primary = replicas[0], replicas = replicas[1], replicas[2]

// Demonstrate stability: same key always returns same replica set
console.log(JSON.stringify(getReplicaSet(ring2, 'user:42', 3)));
console.log(JSON.stringify(getReplicaSet(ring2, 'user:42', 3)));
// Both lines print the same array every time

// Check quorum: with R=3, read from any 2 for QUORUM consistency
function quorumReadCount(replicaFactor) {
  return Math.ceil(replicaFactor / 2) + 1; // majority
}
console.log(quorumReadCount(3)); // 2 — read from 2 of 3
console.log(quorumReadCount(5)); // 3 — read from 3 of 5
